def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape

    # 1. find the border that every coloured row/column touches
    best = None
    for name in ["left", "right", "top", "bottom"]:
        a = g.copy()
        if name == "right":
            a = a[:, ::-1]
        elif name == "top":
            a = a.T
        elif name == "bottom":
            a = a.T[:, ::-1]
        rows = [r for r in range(a.shape[0]) if (a[r] != bg).any()]
        ok = sum(1 for r in rows if a[r, 0] != bg)
        score = (ok == len(rows), ok)
        if best is None or score > best[0]:
            best = (score, name, a)
    _, name, a = best

    def denorm(o):
        if name == "right":
            return o[:, ::-1]
        if name == "top":
            return o.T
        if name == "bottom":
            return o[:, ::-1].T
        return o

    out = a.copy()
    emit(denorm(out), "Lines grow from the %s border; extend each one in turn." % name)

    # 2. extend every line with its period; an on-lattice marker recolours and ends it
    for r in range(a.shape[0]):
        nz = np.nonzero(a[r] != bg)[0]
        if len(nz) < 2 or nz[0] != 0:
            continue
        d = int(nz[1])
        c = a[r, 0]
        end = a.shape[1] - 1
        col = c
        for p in range(2 * d, a.shape[1], d):
            if a[r, p] != bg and a[r, p] != c:
                end = p
                col = a[r, p]
                break
        for p in range(0, end + 1, d):
            out[r, p] = col
        if col != c:
            msg = "Line of colour %d with period %d hits marker %d on its lattice: recolour whole line to %d and stop there." % (c, d, col, col)
        else:
            msg = "Line of colour %d with period %d: repeat it to the far edge (off-lattice cells are left alone)." % (c, d)
        emit(denorm(out), msg)

    result = denorm(out)
    emit(result, "All lines extended; done.")
    return result
